example_usage:
Python:
from redwood import Client
with Client(api_key=...) as c:
    with c.open_stream(model='x') as s:
        for chunk in s:
            print(chunk)

TypeScript:
import {Client} from '@redwood/sdk';
const client = new Client({apiKey: process.env.RW_KEY});
const controller = new AbortController();
for await (const chunk of client.stream(req, {signal: controller.signal})) {
  console.log(chunk);
}

Go:
ctx, cancel := context.WithTimeout(context.Background(), 15*time.Second)
defer cancel()
it := client.Stream(ctx, req)
for {
  chunk, err := it.Next(ctx)
  if err == io.EOF { break }
  if err != nil { log.Fatal(err) }
  fmt.Println(chunk)
}
